const BASE = (typeof window !== 'undefined' && window.__IMG_BASE__) || 'img/';

/** Photo for a deep-dive id, shaped like artifact() in artifact-images.js, or null. */
export function siteArtifact(id) {
  const a = SITE_ARTIFACTS[id];
  if (!a) return null;
  return { ...a, small: BASE + a.w480, large: BASE + a.w900, srcset: `${BASE + a.w480} 480w, ${BASE + a.w900} 900w` };
}
